<script setup lang="ts">
import { computed, onMounted, ref, useId } from 'vue';
import { CharacterCardDefinitionSchema, ScenarioDefinitionSchema } from '@rpg/contracts';
import type { CharacterCardDefinition, ScenarioDefinition, Library as LibraryData, TemplateVersion, TemplateRef, NpcDefinition } from '@rpg/contracts';
import { api } from './api';
import { identityPath } from './identity';
import CharacterForm from './CharacterForm.vue';
import BuilderInvites from './BuilderInvites.vue';
import ErrorNotice from './ErrorNotice.vue';
import FieldGenerator from './FieldGenerator.vue';
import { npcFieldContext } from './field-context';

const helpPrefix = useId();
const helpId = (...parts: string[]) => `${helpPrefix}-help-${encodeURIComponent(JSON.stringify(parts))}`;

const origin = window.location.origin;
const makeId = () => crypto.randomUUID();
const library = ref<LibraryData>({ scenarios: [], characters: [] });
const busy = ref(false);
const error = ref('');
const notice = ref('');
const mode = ref<'scenario' | 'character'>('scenario');
const templateId = ref<string>();
const version = ref(0);
const editorEpoch = ref(0);
const entityContext = (id: string) => `${editorEpoch.value}:${id}`;
const knowledgeKeys = new WeakMap<object, string>();
function knowledgeKey(knowledge: object) {
  let id = knowledgeKeys.get(knowledge);
  if (!id) { id = makeId(); knowledgeKeys.set(knowledge, id); }
  return id;
}
const nativeJson = ref('');
const starterCards = ref<CharacterCardDefinition[]>([]);
const newCard = (): CharacterCardDefinition => ({ schemaVersion: 1, displayName: 'New character', pronouns: '', appearance: '', personality: '', backstory: '', traits: { force: 2, finesse: 1, wits: 1, presence: 0 }, specialty: '', flaw: '', possessions: ['A practical tool', 'A keepsake', 'Travel supplies'], connection: '', secret: '', extensions: {} });
const newScenario = (): ScenarioDefinition => {
  const locationId = crypto.randomUUID();
  return { schemaVersion: 1, title: 'New scenario', premise: '', genre: '', tone: '', boundaries: [], locations: [{ id: locationId, title: 'Opening location', description: '' }], openingScene: { id: crypto.randomUUID(), title: 'Opening scene', description: '', locationId }, npcs: [], tracks: [], facts: [], playerHooks: [], objectives: [], discoveries: [], opportunities: [], directorNotes: '', rulesVersion: '0.1', pacing: { conversationWords: 90, actionWords: 120 }, extensions: {} };
};
const scenario = ref(newScenario());
const card = ref(newCard());
const showTitle = ref('A new story');
const showScenario = ref('');
const characterPremiseSource = ref('');
const draftPremiseLabel = computed(() => `Current scenario draft: ${scenario.value.title}`);
const hasDraftPremise = computed(() => Boolean(scenario.value.premise.trim()) && scenario.value.premise.trim().length <= 4000);
const selectedShowScenario = computed(() => library.value.scenarios.find(item => key(item) === showScenario.value));
const selectedCharacterScenario = computed(() => library.value.scenarios.find(item => key(item) === characterPremiseSource.value));
const savedPremiseLabel = (item: TemplateVersion<ScenarioDefinition>) => `${item.definition.title} · version ${item.version}`;
const characterPremise = computed(() => characterPremiseSource.value === 'draft' ? scenario.value.premise : selectedCharacterScenario.value?.definition.premise);
const characterPremiseLabel = computed(() => characterPremiseSource.value === 'draft' ? draftPremiseLabel.value : selectedCharacterScenario.value ? savedPremiseLabel(selectedCharacterScenario.value) : undefined);
const characterGenerationContext = computed(() => `${editorEpoch.value}:character-source:${characterPremiseSource.value}`);
const seats = ref(['', '']);
const created = ref<Awaited<ReturnType<typeof api.createCustom>> | null>(null);
const listFields = [{ key: 'boundaries', label: 'Content boundaries', help: 'Topics to avoid or handle gently; these guide the artificial intelligence (AI) during play.' }, { key: 'playerHooks', label: 'Player hooks', help: 'Public reasons for the party to join the story; these guide AI scene drafts.' }, { key: 'objectives', label: 'Objectives', help: 'Public goals that guide AI scene drafts; they do not complete automatically.' }, { key: 'discoveries', label: 'Discoveries · director only', help: 'Private ideas for director reference in this template; not loaded into running sessions.' }, { key: 'opportunities', label: 'Opportunities · director only', help: 'Private possibilities for director reference in this template; not loaded into running sessions.' }] as const;
const npcLists = [{ key: 'aliases', label: 'Aliases', help: 'Other names kept as private reference; reveal them deliberately.' }, { key: 'personality', label: 'Personality', help: 'Traits that guide how the AI plays this character.' }, { key: 'limits', label: 'Limits', help: 'Behavioral boundaries that guide this character’s AI dialogue.' }, { key: 'dialogueExamples', label: 'Dialogue examples', help: 'Sample lines that guide this character’s AI speaking style.' }, { key: 'secrets', label: 'Secrets · director only', help: 'Private information for director reference and deliberate reveals.' }] as const;
const lines = (event: Event) => (event.target as HTMLTextAreaElement).value.split('\n');
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value));
function scenarioFromForm() {
  const definition = clone(scenario.value);
  for (const { key } of listFields) definition[key] = definition[key].map(value => value.trim()).filter(Boolean);
  for (const npc of definition.npcs) for (const { key } of npcLists) npc[key] = npc[key].map(value => value.trim()).filter(Boolean);
  return ScenarioDefinitionSchema.parse(definition);
}
function message(cause: unknown) {
  if (cause && typeof cause === 'object' && 'issues' in cause) return `Please enter valid content: ${(cause.issues as Array<{ message: string; path: unknown[] }>).slice(0, 3).map(issue => `${issue.path.join('.')}: ${issue.message}`).join(' · ')}`;
  return cause instanceof Error ? cause.message : 'The library request failed.';
}
async function work(task: () => Promise<void> | void) {
  if (busy.value) return;
  busy.value = true; error.value = ''; notice.value = '';
  try { await task(); } catch (cause) { error.value = message(cause); } finally { busy.value = false; }
}
async function load() {
  editorEpoch.value += 1;
  library.value = await api.library();
  if (!showScenario.value && library.value.scenarios[0]) showScenario.value = key(library.value.scenarios[0]);
  if (library.value.characters[0]) seats.value = seats.value.map(value => value || key(library.value.characters[0]));
}
const key = (item: { id: string; version: number }) => `${item.id}:${item.version}`;
function refFrom(value: string): TemplateRef {
  const split = value.lastIndexOf(':');
  if (split < 1) throw new Error('Choose a saved scenario and a saved card for every seat.');
  return { templateId: value.slice(0, split), version: Number(value.slice(split + 1)) };
}
function editScenario(item?: TemplateVersion<ScenarioDefinition>) { editorEpoch.value += 1; mode.value = 'scenario'; templateId.value = item?.id; version.value = item?.version ?? 0; scenario.value = item ? clone(item.definition) : newScenario(); nativeJson.value = ''; error.value = ''; notice.value = ''; }
function editCard(item?: TemplateVersion<CharacterCardDefinition>) { editorEpoch.value += 1; mode.value = 'character'; characterPremiseSource.value = ''; templateId.value = item?.id; version.value = item?.version ?? 0; card.value = item ? clone(item.definition) : newCard(); nativeJson.value = ''; error.value = ''; notice.value = ''; }
function starter() { return work(async () => { const result = await api.starter(); editScenario(); scenario.value = clone(result.scenario); starterCards.value = clone(result.characters); notice.value = 'Rehearsal content loaded as a new template. Review and save the scenario and any cards you want to reuse.'; }); }
function saveScenario() { return work(async () => {
  const definition = scenarioFromForm();
  const saved = await api.saveScenario({ ...(templateId.value ? { templateId: templateId.value } : {}), expectedVersion: version.value, definition });
  library.value.scenarios = [...library.value.scenarios.filter(item => item.id !== saved.id), saved];
  editScenario(saved); showScenario.value = key(saved); notice.value = `Scenario saved as version ${saved.version}. Existing sessions keep their pinned version.`;
}); }
function saveCard() { return work(async () => {
  const definition = CharacterCardDefinitionSchema.parse({ ...card.value, possessions: card.value.possessions.filter(value => value?.trim()) });
  const saved = await api.saveCharacterTemplate({ ...(templateId.value ? { templateId: templateId.value } : {}), expectedVersion: version.value, definition });
  library.value.characters = [...library.value.characters.filter(item => item.id !== saved.id), saved];
  editCard(saved); seats.value = seats.value.map(value => !value || refFrom(value).templateId === saved.id ? key(saved) : value); notice.value = `Character saved as version ${saved.version}. Selected seats now use this version.`;
}); }
function importJson() { return work(() => {
  let parsed: unknown;
  try { parsed = JSON.parse(nativeJson.value); } catch { throw new Error('Enter a valid native JSON document.'); }
  if (mode.value === 'scenario') { const definition = ScenarioDefinitionSchema.parse(parsed); scenario.value = definition; }
  else { const definition = CharacterCardDefinitionSchema.parse(parsed); card.value = definition; }
  editorEpoch.value += 1; templateId.value = undefined; version.value = 0; notice.value = 'Imported as a new unsaved template. Review the fields before saving.';
}); }
async function importFile(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0];
  if (!file) return;
  if (file.size > 120_000) { error.value = 'Choose a native JSON file smaller than 120 KB.'; return; }
  nativeJson.value = await file.text(); await importJson();
}
function exportJson() { return work(() => {
  const definition = mode.value === 'scenario' ? scenarioFromForm() : CharacterCardDefinitionSchema.parse({ ...card.value, possessions: card.value.possessions.filter(value => value?.trim()) });
  nativeJson.value = JSON.stringify(definition, null, 2);
  const url = URL.createObjectURL(new Blob([JSON.stringify(definition)], { type: 'application/json' }));
  const link = document.createElement('a'); link.href = url; link.download = `${mode.value}.json`; link.click(); URL.revokeObjectURL(url);
  notice.value = 'Native JSON exported. It includes private notes and secrets; share it only with intended collaborators.';
}); }
function addNpc() {
  scenario.value.npcs.push({ id: crypto.randomUUID(), displayName: 'New character', role: '', appearance: '', aliases: [], hiddenIdentity: null, personality: [], motivation: '', goal: '', limits: [], dialogueExamples: [], mood: 'neutral', locationId: scenario.value.openingScene.locationId, status: 'present', communicationChannel: null, voiceProfileId: 'narrator', secrets: [], knowledge: [], partyRelationship: null });
}
function partyRelationship(npc: NpcDefinition, event: Event) {
  const stance = (event.target as HTMLSelectElement).value;
  npc.partyRelationship = stance ? { stance: stance as NonNullable<NpcDefinition['partyRelationship']>['stance'], reason: npc.partyRelationship?.reason ?? '' } : null;
}
function createShow() { return work(async () => {
  if (!showTitle.value.trim()) throw new Error('Enter a session title.');
  if (seats.value.length < 2 || seats.value.length > 6) throw new Error('Choose between two and six player seats.');
  created.value = await api.createCustom(showTitle.value, refFrom(showScenario.value), seats.value.map(refFrom));
}); }
onMounted(() => { void work(load); });
</script>

<template>
  <main class="shell library-shell">
    <div class="scene-heading"><div><p class="eyebrow">Your story library</p><h1>Build a world. Bring a cast.</h1><p>Save reusable scenarios and character cards, then choose two to six seats for your next show.</p></div><a :href="identityPath('/')">Back to host workspace</a></div>
    <ErrorNotice v-if="error" :message="error" @dismiss="error = ''" /><p v-if="notice" role="status" class="notice">{{ notice }}</p>
    <BuilderInvites :disabled="busy" @refresh-library="work(load)" />
    <div class="library-layout">
      <aside class="stack"><section class="panel"><h2>Scenarios</h2><p v-if="!library.scenarios.length" class="muted">No saved scenarios yet.</p><button v-for="item in library.scenarios" :key="item.id" class="library-item secondary" :data-testid="`edit-scenario-${item.id}`" :disabled="busy" @click="editScenario(item)">{{ item.definition.title }} <small>Version {{ item.version }}</small></button><div class="actions"><button class="secondary" :disabled="busy" @click="editScenario()">New scenario</button><button class="quiet" :disabled="busy" @click="starter">Use rehearsal scenario</button></div></section>
      <section class="panel"><h2>Character cards</h2><p v-if="!library.characters.length" class="muted">No saved cards yet.</p><button v-for="item in library.characters" :key="item.id" class="library-item secondary" :data-testid="`edit-character-${item.id}`" :disabled="busy" @click="editCard(item)">{{ item.definition.displayName }} <small>Version {{ item.version }}</small></button><button class="secondary" :disabled="busy" @click="editCard()">New character</button><div v-if="starterCards.length"><h3>Rehearsal cards</h3><button v-for="seed in starterCards" :key="seed.displayName" class="library-item quiet" :disabled="busy" @click="editCard(); card = clone(seed)">Edit {{ seed.displayName }} starter</button></div></section>
      <button class="quiet" :disabled="busy" @click="work(load)">Refresh saved library</button></aside>
      <section class="panel editor"><div class="panel-heading"><h2>{{ mode === 'scenario' ? 'Scenario editor' : 'Character editor' }}</h2><span class="status">{{ version ? `Editing version ${version}` : 'New template' }}</span></div><p class="muted">{{ version ? 'Saving creates a new version. Running sessions keep the version they started with.' : 'Nothing is saved until you choose Save.' }}</p>
      <fieldset class="editor-fields" :disabled="busy"><template v-if="mode === 'scenario'">
        <div class="generated-field"><label><span class="field-label">Scenario title</span><input :aria-describedby="helpId('scenario.title')" v-model="scenario.title" data-testid="scenario-title" maxlength="160"></label><p class="field-help" :id="helpId('scenario.title')">Name used to identify this reusable scenario in the library.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scenario.title" v-model="scenario.title" :context-key="editorEpoch" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Premise</span><textarea :aria-describedby="helpId('scenario.premise')" v-model="scenario.premise" rows="3" /></label><p class="field-help" :id="helpId('scenario.premise')">The public central situation that guides AI scene drafts and optional field drafting.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scenario.premise" v-model="scenario.premise" :context-key="editorEpoch" :disabled="busy" /></div>
        <div class="field-grid"><div class="generated-field"><label><span class="field-label">Genre</span><input :aria-describedby="helpId('scenario.genre')" v-model="scenario.genre"></label><p class="field-help" :id="helpId('scenario.genre')">The public story genre that guides AI scene drafts, such as mystery or fantasy.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scenario.genre" v-model="scenario.genre" :context-key="editorEpoch" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Tone</span><input :aria-describedby="helpId('scenario.tone')" v-model="scenario.tone"></label><p class="field-help" :id="helpId('scenario.tone')">The public mood and style that guide AI scene drafts.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scenario.tone" v-model="scenario.tone" :context-key="editorEpoch" :disabled="busy" /></div></div>
        <div v-for="field in listFields" :key="field.key" class="generated-field"><label><span class="field-label">{{ field.label }} · one per line</span><textarea :aria-describedby="helpId('scenario', field.key)" :value="scenario[field.key].join('\n')" rows="3" @input="scenario[field.key] = lines($event)" /></label><p class="field-help" :id="helpId('scenario', field.key)">{{ field.help }}</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" :field="`scenario.${field.key}`" :model-value="scenario[field.key].join('\n')" :context-key="editorEpoch" :disabled="busy" @update:model-value="scenario[field.key] = $event.split('\n')" /></div>
        <details open><summary>Opening scene & locations</summary><div class="generated-field"><label><span class="field-label">Scene title</span><input :aria-describedby="helpId('scenario.openingScene.title')" v-model="scenario.openingScene.title"></label><p class="field-help" :id="helpId('scenario.openingScene.title')">The title of the first scene when a session begins.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scene.title" v-model="scenario.openingScene.title" :context-key="entityContext(scenario.openingScene.id)" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Scene description</span><textarea :aria-describedby="helpId('scenario.openingScene.description')" v-model="scenario.openingScene.description" /></label><p class="field-help" :id="helpId('scenario.openingScene.description')">The opening situation shown to the table and used as scene context.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scene.description" v-model="scenario.openingScene.description" :context-key="entityContext(scenario.openingScene.id)" :disabled="busy" /></div><div class="help-field"><label>Opening location<select :aria-describedby="helpId('scenario.openingScene.locationId')" v-model="scenario.openingScene.locationId"><option v-for="location in scenario.locations" :key="location.id" :value="location.id">{{ location.title }}</option></select></label><p class="field-help" :id="helpId('scenario.openingScene.locationId')">Choose where the opening scene takes place.</p></div>
          <article v-for="(location, index) in scenario.locations" :key="location.id" class="editor-row"><div class="generated-field"><label><span class="field-label">Location name</span><input :aria-describedby="helpId('location.title', location.id)" v-model="location.title"></label><p class="field-help" :id="helpId('location.title', location.id)">Identifies this place in the director’s location choices.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="location.title" v-model="location.title" :context-key="entityContext(location.id)" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Location description</span><textarea :aria-describedby="helpId('location.description', location.id)" v-model="location.description" /></label><p class="field-help" :id="helpId('location.description', location.id)">Private location notes for the director. Put details the party should see in the scene description.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="location.description" v-model="location.description" :context-key="entityContext(location.id)" :disabled="busy" /></div><button class="quiet" :disabled="scenario.locations.length === 1" @click="scenario.locations.splice(index, 1)">Remove location</button></article><button class="secondary" @click="scenario.locations.push({ id: makeId(), title: 'New location', description: '' })">Add location</button>
        </details>
        <details><summary>Non-player characters · {{ scenario.npcs.length }}</summary><p class="muted">Names, roles, appearances, presence, and voice profile identifiers are public, including offstage characters. Put unrevealed identities and details in hidden identity or secrets.</p><article v-for="(npc, index) in scenario.npcs" :key="npc.id" class="editor-row"><h3>{{ npc.displayName }}</h3><div class="field-grid"><div class="generated-field"><label><span class="field-label">Name</span><input :aria-describedby="helpId('npc.displayName', npc.id)" v-model="npc.displayName"></label><p class="field-help" :id="helpId('npc.displayName', npc.id)">The public name shown to players, even while this character is offstage.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.displayName" v-model="npc.displayName" :context-key="entityContext(npc.id)" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Role</span><input :aria-describedby="helpId('npc.role', npc.id)" v-model="npc.role"></label><p class="field-help" :id="helpId('npc.role', npc.id)">This character’s public role in the story, such as guide or rival.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.role" v-model="npc.role" :context-key="entityContext(npc.id)" :disabled="busy" /></div></div><div class="generated-field"><label><span class="field-label">Appearance</span><textarea :aria-describedby="helpId('npc.appearance', npc.id)" v-model="npc.appearance" /></label><p class="field-help" :id="helpId('npc.appearance', npc.id)">Visible details shared with players, including while this character is offstage.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.appearance" v-model="npc.appearance" :context-key="entityContext(npc.id)" :disabled="busy" /></div><div class="field-grid"><div class="help-field"><label>Location<select :aria-describedby="helpId('npc.locationId', npc.id)" v-model="npc.locationId"><option v-for="location in scenario.locations" :key="location.id" :value="location.id">{{ location.title }}</option></select></label><p class="field-help" :id="helpId('npc.locationId', npc.id)">Where this character starts; present characters must be at the opening location.</p></div><div class="help-field"><label>Presence<select :aria-describedby="helpId('npc.status', npc.id)" v-model="npc.status"><option value="present">Present in opening scene</option><option value="offstage">Offstage</option></select></label><p class="field-help" :id="helpId('npc.status', npc.id)">Whether this character starts physically in the opening scene or offstage; a communication channel can permit remote dialogue.</p></div><div class="help-field"><label>Voice profile · public identifier<input :aria-describedby="helpId('npc.voiceProfileId', npc.id)" v-model="npc.voiceProfileId"></label><p class="field-help" :id="helpId('npc.voiceProfileId', npc.id)">A public voice mapping name for speech; unmapped names use the server’s default voice.</p></div><div class="generated-field"><label><span class="field-label">Mood</span><input :aria-describedby="helpId('npc.mood', npc.id)" v-model="npc.mood"></label><p class="field-help" :id="helpId('npc.mood', npc.id)">The starting mood that guides this character’s AI dialogue.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.mood" v-model="npc.mood" :context-key="entityContext(npc.id)" :disabled="busy" /></div></div><div class="generated-field"><label><span class="field-label">Motivation</span><textarea :aria-describedby="helpId('npc.motivation', npc.id)" v-model="npc.motivation" /></label><p class="field-help" :id="helpId('npc.motivation', npc.id)">Private director reference for what drives this character; not automatically included in AI dialogue.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.motivation" v-model="npc.motivation" :context-key="entityContext(npc.id)" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Current goal</span><textarea :aria-describedby="helpId('npc.goal', npc.id)" v-model="npc.goal" /></label><p class="field-help" :id="helpId('npc.goal', npc.id)">Private director reference for what this character wants next; not automatically included in AI dialogue.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.goal" v-model="npc.goal" :context-key="entityContext(npc.id)" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Hidden identity</span><input :aria-describedby="helpId('npc.hiddenIdentity', npc.id)" v-model="npc.hiddenIdentity"></label><p class="field-help" :id="helpId('npc.hiddenIdentity', npc.id)">Private identity for director reference and a deliberate reveal.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.hiddenIdentity" :model-value="npc.hiddenIdentity ?? ''" @update:model-value="npc.hiddenIdentity = $event" :context-key="entityContext(npc.id)" :disabled="busy" /></div><div class="generated-field"><label><span class="field-label">Communication channel</span><input :aria-describedby="helpId('npc.communicationChannel', npc.id)" v-model="npc.communicationChannel"></label><p class="field-help" :id="helpId('npc.communicationChannel', npc.id)">A channel such as radio that permits remote dialogue and guides AI drafts; it does not connect a real service.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.communicationChannel" :model-value="npc.communicationChannel ?? ''" @update:model-value="npc.communicationChannel = $event" :context-key="entityContext(npc.id)" :disabled="busy" /></div>
          <div v-for="field in npcLists" :key="field.key" class="generated-field"><label><span class="field-label">{{ field.label }} · one per line</span><textarea :aria-describedby="helpId('npc', npc.id, field.key)" :value="npc[field.key].join('\n')" @input="npc[field.key] = lines($event)" /></label><p class="field-help" :id="helpId('npc', npc.id, field.key)">{{ field.help }}</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" :field="`npc.${field.key}`" :model-value="npc[field.key].join('\n')" :context-key="entityContext(npc.id)" :disabled="busy" @update:model-value="npc[field.key] = $event.split('\n')" /></div><div class="help-field"><label>Relationship to the party<select :aria-describedby="helpId('npc.partyRelationship', npc.id)" :value="npc.partyRelationship?.stance ?? ''" @change="partyRelationship(npc, $event)"><option value="">No established relationship</option><option v-for="stance in ['hostile', 'wary', 'neutral', 'friendly', 'trusting']" :key="stance">{{ stance }}</option></select></label><p class="field-help" :id="helpId('npc.partyRelationship', npc.id)">The starting attitude toward the party, used in AI dialogue context.</p></div><div v-if="npc.partyRelationship" class="generated-field"><label><span class="field-label">Relationship reason</span><textarea :aria-describedby="helpId('npc.partyRelationship.reason', npc.id)" v-model="npc.partyRelationship.reason" /></label><p class="field-help" :id="helpId('npc.partyRelationship.reason', npc.id)">Why this character holds that attitude; guides AI dialogue.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.relationshipReason" v-model="npc.partyRelationship.reason" :context-key="entityContext(npc.id)" :disabled="busy" /></div><div v-for="(knowledge, memoryIndex) in npc.knowledge" :key="knowledgeKey(knowledge)" class="editor-row"><div class="generated-field"><label><span class="field-label">What this character knows</span><textarea :aria-describedby="helpId('knowledge.statement', npc.id, knowledgeKey(knowledge))" v-model="knowledge.statement" /></label><p class="field-help" :id="helpId('knowledge.statement', npc.id, knowledgeKey(knowledge))">A fact, belief, or claim available to this character’s AI dialogue.</p><FieldGenerator :character-context="npcFieldContext(npc)" :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="npc.knowledge" v-model="knowledge.statement" :context-key="entityContext(knowledgeKey(knowledge))" :disabled="busy" /></div><div class="help-field"><label>Knowledge type<select :aria-describedby="helpId('knowledge.category', npc.id, knowledgeKey(knowledge))" v-model="knowledge.category"><option>fact</option><option>belief</option><option>claim</option></select></label><p class="field-help" :id="helpId('knowledge.category', npc.id, knowledgeKey(knowledge))">Distinguish established knowledge from a belief or a reported claim.</p></div><button class="quiet" @click="npc.knowledge.splice(memoryIndex, 1)">Remove knowledge</button></div><div class="actions"><button class="secondary" @click="npc.knowledge.push({ statement: '', category: 'fact' })">Add knowledge</button><button class="quiet" @click="scenario.npcs.splice(index, 1)">Remove character</button></div></article><button class="secondary" @click="addNpc">Add non-player character</button></details>
        <details><summary>Tracks & facts</summary><article v-for="(track, index) in scenario.tracks" :key="track.id" class="editor-row"><div class="generated-field"><label><span class="field-label">Track label</span><input :aria-describedby="helpId('track.label', track.id)" v-model="track.label"></label><p class="field-help" :id="helpId('track.label', track.id)">The name used to identify this track during play.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="track.label" v-model="track.label" :context-key="entityContext(track.id)" :disabled="busy" /></div><div class="field-grid"><div class="help-field"><label>Track kind<select :aria-describedby="helpId('track.kind', track.id)" v-model="track.kind"><option>progress</option><option>danger</option><option>countdown</option></select></label><p class="field-help" :id="helpId('track.kind', track.id)">Use progress for a goal, danger for growing trouble, or countdown for an approaching event. Set automatic ticking separately.</p></div><div class="help-field"><label>Visibility<select :aria-describedby="helpId('track.visibility', track.id)" v-model="track.visibility"><option>public</option><option>director</option></select></label><p class="field-help" :id="helpId('track.visibility', track.id)">Public tracks are shown to players; director tracks stay private.</p></div><div class="help-field"><label>Current<input :aria-describedby="helpId('track.current', track.id)" v-model.number="track.current" type="number" min="0" :max="track.max"></label><p class="field-help" :id="helpId('track.current', track.id)">The starting value, between zero and the maximum.</p></div><div class="help-field"><label>Maximum<input :aria-describedby="helpId('track.max', track.id)" v-model.number="track.max" type="number" min="1" max="8"></label><p class="field-help" :id="helpId('track.max', track.id)">The track’s upper limit, from 1 to 8.</p></div></div><div class="help-field"><label>Tick automatically<select :aria-describedby="helpId('track.trigger', track.id)" v-model="track.trigger"><option :value="null">Never</option><option value="action_round">After each action round</option></select></label><p class="field-help" :id="helpId('track.trigger', track.id)">With “After each action round” selected, enabled countdowns advance by 1 toward their maximum after a published action round; other track kinds do not tick.</p></div><div class="help-field"><label class="check"><input :aria-describedby="helpId('track.enabled', track.id)" v-model="track.enabled" type="checkbox">Enabled at start</label><p class="field-help" :id="helpId('track.enabled', track.id)">Whether this track starts active; inactive countdowns do not tick, but typed effects can still change tracks.</p></div><div class="generated-field"><label><span class="field-label">Completion text</span><textarea :aria-describedby="helpId('track.completionText', track.id)" v-model="track.completionText" /></label><p class="field-help" :id="helpId('track.completionText', track.id)">Describe what happens when this track fills; text alone creates no mechanical effect. On public tracks, this wording is visible immediately.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="track.completionText" v-model="track.completionText" :context-key="entityContext(track.id)" :disabled="busy" /></div><small>Completion effects are preserved. Use the complete native JSON below for typed countdown completion effects. Only countdowns tick after action rounds; completion effects may change other progress/danger tracks or add new facts. Public completion text is visible to players.</small><button class="quiet" @click="scenario.tracks.splice(index, 1)">Remove track</button></article><button class="secondary" @click="scenario.tracks.push({ id: makeId(), label: 'New track', kind: 'progress', current: 0, max: 4, visibility: 'public', trigger: null, enabled: true, completionText: '', completionEffects: [] })">Add track</button>
          <article v-for="(fact, index) in scenario.facts" :key="fact.id" class="editor-row"><div class="generated-field"><label><span class="field-label">Established fact</span><textarea :aria-describedby="helpId('fact.text', fact.id)" v-model="fact.text" /></label><p class="field-help" :id="helpId('fact.text', fact.id)">An established detail included in the session’s starting facts.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="fact.text" v-model="fact.text" :context-key="entityContext(fact.id)" :disabled="busy" /></div><div class="help-field"><label>Visibility<select :aria-describedby="helpId('fact.visibility', fact.id)" v-model="fact.visibility"><option>public</option><option>director</option></select></label><p class="field-help" :id="helpId('fact.visibility', fact.id)">Public facts are shown to players; director facts stay private.</p></div><button class="quiet" @click="scenario.facts.splice(index, 1)">Remove fact</button></article><button class="secondary" @click="scenario.facts.push({ id: makeId(), text: '', visibility: 'public' })">Add fact</button></details>
        <div class="generated-field"><label><span class="field-label">Director notes</span><textarea :aria-describedby="helpId('scenario.directorNotes')" v-model="scenario.directorNotes" rows="5" /></label><p class="field-help" :id="helpId('scenario.directorNotes')">Private director reference for running this scenario; not automatically included in AI scene drafts.</p><FieldGenerator :premise="scenario.premise" :premise-label="draftPremiseLabel" class="field-ai" field="scenario.directorNotes" v-model="scenario.directorNotes" :context-key="editorEpoch" :disabled="busy" /></div><div class="field-grid"><div class="help-field"><label>Conversation word target<input :aria-describedby="helpId('scenario.pacing.conversationWords')" v-model.number="scenario.pacing.conversationWords" type="number" min="20" max="300"></label><p class="field-help" :id="helpId('scenario.pacing.conversationWords')">Approximate word target for AI conversation drafts, from 20 to 300.</p></div><div class="help-field"><label>Action word target<input :aria-describedby="helpId('scenario.pacing.actionWords')" v-model.number="scenario.pacing.actionWords" type="number" min="30" max="500"></label><p class="field-help" :id="helpId('scenario.pacing.actionWords')">Approximate word target for AI action drafts, from 30 to 500.</p></div></div><p class="field-help">Saving creates a new reusable version; running sessions remain unchanged.</p><button :disabled="busy" data-testid="save-scenario" @click="saveScenario">Save scenario version</button>
      </template>
      <template v-else><div class="help-field"><label>Scenario for AI drafts<select :aria-describedby="helpId('characterPremiseSource')" v-model="characterPremiseSource" data-testid="character-premise-source" :disabled="busy"><option value="">No scenario selected</option><option v-if="hasDraftPremise" value="draft">{{ draftPremiseLabel }}</option><option v-for="item in library.scenarios" :key="key(item)" :value="key(item)">{{ savedPremiseLabel(item) }}</option></select></label><p class="field-help" :id="helpId('characterPremiseSource')">Choose context for AI drafts; this does not save a link between the character and scenario.</p></div><CharacterForm v-model="card" :disabled="busy" generation-enabled :generation-context="characterGenerationContext" :premise="characterPremise" :premise-label="characterPremiseLabel" /><p class="field-help">Saving creates a new reusable version; running sessions remain unchanged.</p><button :disabled="busy" data-testid="save-character" @click="saveCard">Save character version</button></template>
      <details><summary>Native JSON import, export & advanced editing</summary><p class="muted">Only this app’s version 1 format is accepted. Import validates the complete document and opens a new unsaved template. No scripts or external resources are loaded.</p><div class="help-field"><label>Native JSON<textarea :aria-describedby="helpId('nativeJson')" v-model="nativeJson" data-testid="native-json" rows="12" spellcheck="false" /></label><p class="field-help" :id="helpId('nativeJson')">Edit this app’s native JavaScript Object Notation (JSON) document, then import to replace the unsaved form. Exports include private notes and secrets.</p></div><div class="actions"><button class="secondary" :disabled="busy" data-testid="import-json" @click="importJson">Import native JSON</button><button class="secondary" :disabled="busy" @click="exportJson">Export native JSON</button><button class="quiet" @click="nativeJson = JSON.stringify(mode === 'scenario' ? scenario : card, null, 2)">Copy current fields into editor</button></div><div class="help-field"><label>Import a native JSON file<input :aria-describedby="helpId('file')" type="file" accept="application/json,.json" @change="importFile"></label><p class="field-help" :id="helpId('file')">Load a native JSON file up to 120 KB as a new unsaved template for review.</p></div></details>
      </fieldset></section>
    </div>
    <section class="panel create-show"><p class="eyebrow">Bring it to the table</p><h2>Create a custom show</h2><template v-if="!created"><div class="generated-field"><label><span class="field-label">Session title</span><input :aria-describedby="helpId('showTitle')" v-model="showTitle" data-testid="show-title" maxlength="160"></label><p class="field-help" :id="helpId('showTitle')">The title displayed for this session.</p><FieldGenerator :premise="selectedShowScenario?.definition.premise" :premise-label="selectedShowScenario ? savedPremiseLabel(selectedShowScenario) : undefined" class="field-ai" field="session.title" v-model="showTitle" :context-key="`${editorEpoch}:new-show:${showScenario}`" :disabled="busy" /></div><div class="help-field"><label>Scenario version<select :aria-describedby="helpId('showScenario')" v-model="showScenario" data-testid="show-scenario" :disabled="busy"><option value="">Choose a saved scenario</option><option v-for="item in library.scenarios" :key="key(item)" :value="key(item)">{{ item.definition.title }} · version {{ item.version }}</option></select></label><p class="field-help" :id="helpId('showScenario')">Choose the saved scenario version to copy into the new session.</p></div><div v-for="(_, index) in seats" :key="index" class="seat-row"><div class="help-field"><label>Player seat {{ index + 1 }}<select :aria-describedby="helpId('seats[index]', String(index))" v-model="seats[index]" :disabled="busy" :data-testid="`show-seat-${index}`"><option value="">Choose a saved character</option><option v-for="item in library.characters" :key="key(item)" :value="key(item)">{{ item.definition.displayName }} · version {{ item.version }}</option></select></label><p class="field-help" :id="helpId('seats[index]', String(index))">Choose a saved character version; each seat gets its own editable copy.</p></div><button class="quiet" :disabled="seats.length <= 2" @click="seats.splice(index, 1)">Remove seat</button></div><p class="muted">Each seat gets its own editable card draft. Reusing a template creates independent characters.</p><div class="actions"><button class="secondary" :disabled="seats.length >= 6" @click="seats.push('')">Add player seat</button><button :disabled="busy || !showScenario || seats.some(value => !value)" data-testid="create-custom" @click="createShow">Create custom session</button></div></template>
    <template v-else><h3>Your custom table is ready.</h3><p>Save these single-use invitations now. Players review their own cards and boundaries in the lobby before the director starts.</p><div v-for="(invite, index) in created.invites" :key="invite.token"><label>{{ invite.role === 'stage' ? 'Broadcast stage' : `Player ${index + 1}` }}<input :aria-describedby="helpId('invite', invite.token)" :aria-label="invite.role === 'stage' ? 'Stage invitation' : `Player ${index + 1} invitation`" :value="`${origin}/join/${encodeURIComponent(invite.token)}`" readonly @focus="($event.target as HTMLInputElement).select()"></label><p class="field-help" :id="helpId('invite', invite.token)">Share this single-use invitation with its intended player or broadcast stage.</p></div><a class="button" data-testid="custom-lobby-link" :href="identityPath(`/sessions/${created.sessionId}/lobby`)">Review cast & lobby</a></template></section>
  </main>
</template>

